    /** Rows the in-app picker may show after explicit catalogue promotion and readiness. */
    val pickerRows: List<SupportedLocale> get() = all.filter {
        (it.id == "en-US" || it.coverage >= TRANSLATION_READINESS_THRESHOLD_PERCENT) &&
            it.packaged && it.pickerVisible
    }

    /** A community locale is ready for manual packaging/picker promotion at the readiness threshold or above. */
    fun isTranslationReady(coverage: Int): Boolean =
        coverage >= TRANSLATION_READINESS_THRESHOLD_PERCENT

    /** Visible community coverage badge; complete/source/system rows have no badge. */
    fun coverageBadgePercent(locale: SupportedLocale): Int? =
        locale.coverage.takeIf { locale.tier == 1 && locale.id != "en-US" && locale.pickerVisible && it < 100 }

    /** Canonicalize a supported runtime tag; empty means follow the system locale. */
    fun canonicalTag(raw: String?): String? {
        val trimmed = raw?.trim() ?: return null
        if (trimmed.isEmpty()) return SYSTEM_DEFAULT_TAG
        return all.firstOrNull { it.languageTag.equals(trimmed, ignoreCase = true) }?.languageTag
    }

    /** Look up the ISO 15924 script for a BCP-47 tag, or null if it is not a catalogue entry. */
    fun scriptForTag(tag: String): String? =
        all.firstOrNull { it.languageTag == tag }?.script

    /** True for an RTL script (Arabic, ...). False for the system-default empty tag. */
    fun isRtl(tag: String): Boolean = all.firstOrNull { it.languageTag == tag }?.rtl == true
}
